const c=require('./common');
(async()=>{try{let out=n=>{let f=process.env.GITHUB_OUTPUT;if(f)require('fs').appendFileSync(f,`${n}\n`)};let repo=c.input('repository'),key=c.input('key'),m=await c.refs(repo), candidates=[key,...c.input('restore-keys').split(/\r?\n/).map(x=>x.trim()).filter(Boolean)];let found=null;for(let prefix of candidates){let rows=Object.entries(m.json.references).filter(([k,v])=>k===prefix||k.startsWith(prefix)).filter(([,v])=>v&&v.object).sort((a,b)=>String(b[1].updated_at).localeCompare(String(a[1].updated_at)));if(rows.length){found=rows[0];break}}if(!found){out('cache-hit=false');return}let f=await c.download(repo,found[1].object);c.extract(f);out(`cache-hit=${found[0]===key}`);out(`matched-key=${found[0]}`);out(`content-hash=${found[1].object}`);out(`cache-size=${require('fs').statSync(f).size}`);console.log(`Cache hit: ${found[0]===key}; matched key: ${found[0]}; object: ${found[1].object}`)}catch(e){c.fail(e)}})();
